func startControllerStorageCapacity(ctx context.Context, cfg Config, runtime *natscell.Runtime, fullClusterReady func() bool) (func(), error) {
	if cfg.NATS.Embedded == nil || runtime == nil {
		return nil, errors.New("storage capacity requires the embedded regional NATS server")
	}
	store, _, err := retryControllerOpen(ctx, "open storage usage bucket", fullClusterReady, false,
		func(attempt context.Context) (*capacity.UsageStore, error) {
			return capacity.OpenUsageStore(attempt, runtime.JetStream(), cfg.NATS.Replicas, storage.DefaultUsageTTL, capacity.DefaultPolicy())
		}, nil)
	if err != nil {
		return nil, err
	}
	collector := capacity.Collector{
		Cell: cfg.NATS.Cell, Node: cfg.NATS.Instance,
		Targets: capacity.ControllerTargets(cfg.NATS.Embedded.StoreDir, runtime.LocalStoreUsedBytes, cfg.NATS.Embedded.StoreLimitBytes()),
	}
	return ownedLoop(ctx, "controller storage capacity collector", func(ctx context.Context) error {
		return capacity.Run(ctx, collector, store, capacity.DefaultPolicy(), storage.DefaultCollectInterval, capacity.LogSignal)
	}), nil
}

// ownedLoop runs a background service under a context the caller owns. The
// returned stop cancels it and waits until it has returned, so no loop
// outlives the dependencies the caller closes afterwards.
func ownedLoop(parent context.Context, name string, run func(context.Context) error) func() {
	ctx, cancel := context.WithCancel(parent)
	done := make(chan struct{})
	go func() {
		defer close(done)
		if err := run(ctx); err != nil && ctx.Err() == nil {
			slog.ErrorContext(ctx, name+" stopped", "error", err)
		}
	}()
	return func() {
		cancel()
		<-done
	}
}

func (collector Collector) Collect(ctx context.Context) ([]VolumeUsage, error) {
	statfs := collector.Statfs
	if statfs == nil {
		statfs = Statfs
	}
	now := time.Now
	if collector.Now != nil {
		now = collector.Now
	}
	var usages []VolumeUsage
	var failures []error
	for _, target := range collector.Targets {
		stat, err := statfs(target.Path)
		if err != nil {
			failures = append(failures, fmt.Errorf("measure %s %s: %w", target.Role, target.Path, err))
			continue
		}
		usage := VolumeUsage{
			Cell: collector.Cell, Node: collector.Node, Role: target.Role, VolumeID: target.VolumeID,
			MountPath: target.Path, TotalBytes: stat.TotalBytes, UsedBytes: stat.TotalBytes - min(stat.TotalBytes, stat.FreeBytes),
			AvailBytes: stat.AvailBytes, InodesTotal: stat.InodesTotal, InodesFree: stat.InodesFree,
			ObservedAt: now().UTC(),
		}
		if target.Reserve != nil {
			reserved, err := target.Reserve(ctx)
			if err != nil {
				failures = append(failures, fmt.Errorf("measure %s reservation: %w", target.Role, err))
				continue
			}
			usage.ReservedBytes = reserved
		}
		if err := usage.Validate(); err != nil {
			failures = append(failures, fmt.Errorf("measure %s %s: %w", target.Role, target.Path, err))
			continue
		}
		usages = append(usages, usage)
	}
	return usages, errors.Join(failures...)
}

// StoreUsage reports how many bytes the embedded JetStream server stores on
// this node. It must be node-local: an account's usage also counts the
// replicas other nodes store.
type StoreUsage func(context.Context) (uint64, error)

// JetStreamReservation reports the unused part of this node's JetStream
// max-store limit: space the embedded server may still claim on its
// StoreDir. The limit is per node, so it is compared with node-local usage.
func JetStreamReservation(used StoreUsage, maxStoreBytes int64) func(context.Context) (uint64, error) {
	return func(ctx context.Context) (uint64, error) {
		if used == nil || maxStoreBytes <= 0 {
			return 0, errors.New("JetStream reservation requires a node-local usage source and a positive store limit")
		}
		stored, err := used(ctx)
		if err != nil {
			return 0, fmt.Errorf("read JetStream node usage: %w", err)
		}
		limit := uint64(maxStoreBytes)
		return limit - min(limit, stored), nil
	}
}

// ControllerTargets measures a controller node: its boot root and the
// embedded JetStream StoreDir, whose unused max-store reservation counts as
// promised space.
func ControllerTargets(storeDir string, used StoreUsage, maxStoreBytes int64) []Target {
	return []Target{
		{Role: storage.RoleBoot, Path: "/"},
		{Role: storage.RoleJetStream, Path: storeDir, Reserve: JetStreamReservation(used, maxStoreBytes)},
	}
}

func Run(ctx context.Context, collector Collector, publisher Publisher, policy Policy, interval time.Duration, onSignal func(Signal)) error {
	if publisher == nil || interval <= 0 {
		return errors.New("storage capacity collector requires a publisher and a positive interval")
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		usages, err := collector.Collect(ctx)
		if err != nil {
			slog.WarnContext(ctx, "storage capacity measurement failed", "error", err)
		}
		for _, usage := range usages {
			if err := publisher.Publish(ctx, usage); err != nil && ctx.Err() == nil {
				slog.WarnContext(ctx, "storage capacity publish failed", "role", usage.Role, "path", usage.MountPath, "error", err)
			}
			if signal := Evaluate(usage, policy); signal.Level != LevelOK && onSignal != nil {
				onSignal(signal)
			}
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func Statfs(path string) (FSStat, error) {
	var stat unix.Statfs_t
	if err := unix.Statfs(path, &stat); err != nil {
		return FSStat{}, fmt.Errorf("statfs %s: %w", path, err)
	}
	blockSize := uint64(stat.Bsize)
	return FSStat{
		TotalBytes: stat.Blocks * blockSize, FreeBytes: stat.Bfree * blockSize, AvailBytes: stat.Bavail * blockSize,
		InodesTotal: stat.Files, InodesFree: stat.Ffree,
	}, nil
}

func OpenUsageStore(ctx context.Context, js jetstream.JetStream, replicas int, ttl time.Duration, policy Policy) (*UsageStore, error) {
	if js == nil || replicas < 1 || replicas > 5 || ttl < time.Second || ttl > time.Hour {
		return nil, errors.New("storage usage store requires JetStream, one to five replicas and a TTL between 1s and 1h")
	}
	if err := policy.Validate(); err != nil {
		return nil, err
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       UsageBucket,
		Description:  "TTL'd storage capacity measurements",
		MaxValueSize: usageMaxValueSize,
		History:      1,
		TTL:          ttl,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create storage usage bucket: %w", err)
		}
		if kv, err = js.KeyValue(ctx, UsageBucket); err != nil {
			return nil, fmt.Errorf("open storage usage bucket: %w", err)
		}
		status, err := kv.Status(ctx)
		if err != nil {
			return nil, fmt.Errorf("inspect storage usage bucket: %w", err)
		}
		if status.TTL() != ttl {
			// The requested TTL was validated against the collection
			// interval; an older bucket TTL could expire live measurements
			// before the next publish, so reconcile it.
			if kv, err = js.UpdateKeyValue(ctx, jetstream.KeyValueConfig{
				Bucket: UsageBucket, Description: "TTL'd storage capacity measurements",
				MaxValueSize: usageMaxValueSize, History: 1, TTL: ttl,
				Storage: jetstream.FileStorage, Replicas: replicas,
			}); err != nil {
				return nil, fmt.Errorf("reconcile storage usage bucket TTL from %s to %s: %w", status.TTL(), ttl, err)
			}
		}
	}
	return &UsageStore{kv: kv, ttl: ttl, policy: policy, now: time.Now}, nil
}

func usageKey(usage VolumeUsage) string {
	return entityid.Derive("storage-usage", usage.Cell, usage.Node, string(usage.Role), usage.VolumeID, usage.MountPath)
}

// Publish stores one validated measurement under its stable key.
func (store *UsageStore) Publish(ctx context.Context, usage VolumeUsage) error {
	if err := usage.Validate(); err != nil {
		return err
	}
	data, err := json.Marshal(usage)
	if err != nil {
		return fmt.Errorf("encode storage usage: %w", err)
	}
	if _, err := store.kv.Put(ctx, usageKey(usage), data); err != nil {
		return fmt.Errorf("publish storage usage: %w", err)
	}
	return nil
}

// Usages returns every current measurement. Records older than the TTL are
// skipped even if the server has not purged them yet.
func (store *UsageStore) Usages(ctx context.Context) ([]VolumeUsage, error) {
	lister, err := store.kv.ListKeys(ctx)
	if err != nil {
		return nil, fmt.Errorf("list storage usage: %w", err)
	}
	defer func() { _ = lister.Stop() }()
	now := store.now()
	var usages []VolumeUsage
	for key := range lister.Keys() {
		if len(usages) >= maxUsageRecords {
			return nil, errors.New("storage usage inventory exceeds its safety bound")
		}
		entry, err := store.kv.Get(ctx, key)
		if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read storage usage: %w", err)
		}
		var usage VolumeUsage
		if err := json.Unmarshal(entry.Value(), &usage, json.RejectUnknownMembers(true)); err != nil {
			return nil, fmt.Errorf("decode storage usage: %w", err)
		}
		if usage.Validate() != nil || usageKey(usage) != key || now.Sub(usage.ObservedAt) > store.ttl {
			continue
		}
		usages = append(usages, usage)
	}
	// The key lister closes its channel early, without an error, when ctx
	// ends mid-listing (its Stop only unsubscribes): a truncated inventory
	// must not look complete, or live nodes would read as expired.
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list storage usage: %w", err)
	}
	return usages, nil
}

