type volumeListStore struct {
	placement.Store
	intents []placement.Intent
	members map[string][]placement.VersionedMemberState
}

func (store volumeListStore) ListIntents(context.Context) ([]placement.Intent, error) {
	return store.intents, nil
}

func (store volumeListStore) ListMembers(_ context.Context, databaseID, partitionID string) ([]placement.VersionedMemberState, error) {
	if members, ok := store.members[databaseID+"/"+partitionID]; ok {
		return members, nil
	}
	return nil, errors.New("partition unreadable")
}

func (volumeListStore) ReadTerminalIntent(context.Context, string, string) (authority.LogEntry, error) {
	return authority.LogEntry{}, errors.New("unused")
}

func placementVolumeIDs(ctx context.Context, store placement.Store) ([]string, error) {
	members, skipped, err := placedVolumeMembers(ctx, store, true)
	if err != nil {
		return nil, err
	}
	volumes := make([]string, 0, len(members))
	for _, member := range members {
		volumes = append(volumes, member.VolumeID)
	}
	if len(skipped) > 0 {
		slog.WarnContext(ctx, "volume backup listing skipped unreadable partitions", "error", errors.Join(skipped...))
		return volumes, fmt.Errorf("%w: %w", backup.ErrPartialVolumes, errors.Join(skipped...))
	}
	return volumes, nil
}

func placedVolumeMembers(ctx context.Context, store placement.Store, skipUnreadable bool) (out []placement.MemberState, skipped []error, err error) {
	intents, err := store.ListIntents(ctx)
	if err != nil {
		return nil, nil, err
	}
	seen := make(map[string]bool)
	for _, intent := range intents {
		members, err := store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			if !skipUnreadable {
				return nil, nil, err
			}
			skipped = append(skipped, fmt.Errorf("partition %s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
			continue
		}
		for _, member := range members {
			if id := member.State.VolumeID; id != "" && member.State.Stage != placement.StageRemoved && !seen[id] {
				seen[id] = true
				out = append(out, member.State)
			}
		}
	}
	return out, skipped, nil
}

config_rejection.text:
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

func readHostLocalOptions(path string) (hostLocalOptions, error) {
	file, err := os.Open(path)
	if errors.Is(err, os.ErrNotExist) {
		return hostLocalOptions{}, nil
	}
	if err != nil {
		return hostLocalOptions{}, fmt.Errorf("read existing host config: %w", err)
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, 1<<20+1))
	if err != nil {
		return hostLocalOptions{}, fmt.Errorf("read existing host config: %w", err)
	}
	if len(data) > 1<<20 {
		return hostLocalOptions{}, errors.New("existing host config is too large")
	}
	if _, err := decodeConfig(data); err != nil {
		return hostLocalOptions{}, fmt.Errorf("decode existing host config %s (repair it before renewing): %w", path, err)
	}
	var existing struct {
		Host hostLocalOptions `json:"host"`
	}
	if err := json.Unmarshal(data, &existing); err != nil {
		return hostLocalOptions{}, fmt.Errorf("decode existing host config %s (repair it before renewing): %w", path, err)
	}
	return existing.Host, nil
}

