func terraBaseSeats(peers string) map[string]WorkloadProfile {
	return map[string]WorkloadProfile{terrabase.Role: {Env: map[string]string{
		"TERRABASE_REGION": "gru-1", "TERRABASE_PEER_PORT": "9443", "TERRABASE_CLIENT_PORT": "9465", "TERRABASE_PEERS": peers}}}
}

func terraBaseSeatMembers(profiles map[string]WorkloadProfile, public *OciReconcileLBConfig) ([]seatrollout.Member, error) {
	profile, ok := profiles[terrabase.Role]
	if !ok {
		if public != nil {
			return nil, errors.New("public load balancer: the cell has no terrabase workload profile")
		}
		return nil, nil
	}
	if public == nil {
		return nil, errors.New("TerraBase seat restarts require signed public load balancer authority")
	}
	if _, err := public.spec(profiles, nil); err != nil {
		return nil, err
	}
	parsed, err := terrabase.ParseProfile(profile.Env)
	if err != nil {
		return nil, err
	}
	members := make([]seatrollout.Member, 0, len(parsed.Peers))
	for _, peer := range parsed.Peers {
		member := seatrollout.Member{Node: peer.Name, Group: terrabase.Role}
		if len(public.Seats) == 0 || slices.Contains(public.Seats, peer.Name) {
			member.Backend = peer.Address.Addr().String() + ":" + strconv.Itoa(parsed.ClientPort)
		}
		members = append(members, member)
	}
	return members, nil
}

func lbSeatBackends(api lb.API, public OciReconcileLBConfig) func(context.Context) (map[string]seatrollout.Backend, error) {
	return func(ctx context.Context) (map[string]seatrollout.Backend, error) {
		backends, err := api.ListBackends(ctx, public.LoadBalancerID, public.BackendSet)
		if err != nil {
			return nil, err
		}
		unhealthy, err := api.UnhealthyBackends(ctx, public.LoadBalancerID, public.BackendSet)
		if err != nil {
			return nil, err
		}
		out := make(map[string]seatrollout.Backend, len(backends))
		for _, backend := range backends {
			out[backend.IP+":"+strconv.Itoa(backend.Port)] = seatrollout.Backend{Drained: backend.Drain, Healthy: !unhealthy[backend.Name()]}
		}
		return out, nil
	}
}

func (c OciReconcileLBConfig) spec(profiles map[string]WorkloadProfile, drained map[string]bool) (lb.Spec, error) {
	profile, ok := profiles[terrabase.Role]
	if !ok {
		return lb.Spec{}, errors.New("public load balancer: the cell has no terrabase workload profile")
	}
	members, err := terrabase.ParseProfile(profile.Env)
	if err != nil {
		return lb.Spec{}, fmt.Errorf("public load balancer: %w", err)
	}
	if members.ClientPort == 0 {
		return lb.Spec{}, errors.New("public load balancer: the terrabase profile has no client listener")
	}
	spec := lb.Spec{LoadBalancerID: c.LoadBalancerID, BackendSet: c.BackendSet}
	for _, seat := range c.Seats {
		if _, ok := members.Peer(seat); !ok {
			return lb.Spec{}, fmt.Errorf("public load balancer seat %q is not in %s", seat, terrabase.EnvPeers)
		}
	}
	for _, peer := range members.Peers {
		if len(c.Seats) == 0 || slices.Contains(c.Seats, peer.Name) {
			spec.Backends = append(spec.Backends, lb.Backend{IP: peer.Address.Addr().String(), Port: members.ClientPort,
				Drain: drained[peer.Name]})
		}
	}
	return spec, nil
}

type seatLBAPI struct {
	lb.API
	backends  []lb.Backend
	unhealthy map[string]bool
}

func (a seatLBAPI) ListBackends(context.Context, string, string) ([]lb.Backend, error) {
	return a.backends, nil
}

func (a seatLBAPI) UnhealthyBackends(context.Context, string, string) (map[string]bool, error) {
	return a.unhealthy, nil
}

