func (c *Controller) Tick(ctx context.Context) error {
	snapshot := c.Fencer.Current()
	if !snapshot.CanMutate() {
		c.ready, c.drained = nil, nil
		return nil
	}
	views, err := c.observe(ctx)
	if err != nil {
		return err
	}
	// Keep only the waits of seats that are drained now, so a seat that
	// left and came back, or was returned, starts them afresh.
	ready, drained := map[string]time.Time{}, map[string]time.Time{}
	for _, v := range views {
		if v.record.Drain {
			if at, ok := c.ready[v.seat.Node]; ok {
				ready[v.seat.Node] = at
			}
			if at, ok := c.drained[v.seat.Node]; ok {
				drained[v.seat.Node] = at
			}
		}
	}
	c.ready, c.drained = ready, drained
	now := c.now()
	busy := map[string]bool{}
	for _, v := range views {
		record, target := v.record, v.desired.Generation
		switch {
		case record.Drain && v.wanted && v.done && record.Permit >= target && (!v.inLB || v.backend.Healthy):
			// Restarted and serving: back to rotation once the seat has kept
			// serving for the settle time, its /readyz included, and the load
			// balancer also finds it healthy. If OCI stopped checking a
			// drained backend the seat stays drained and its group waits,
			// which costs time, never requests. A seat whose desired was
			// withdrawn stays drained, holding its group, while its host stops
			// it: it serves nothing and its group is a member short.
			first, seen := c.ready[v.seat.Node]
			if !seen {
				c.ready[v.seat.Node] = now
				first = now
			}
			if now.Sub(first) < DefaultSettle {
				busy[v.seat.Group] = true
				continue
			}
			delete(c.ready, v.seat.Node)
			record.Drain, record.DrainedAt = false, time.Time{}
			if err := c.put(ctx, snapshot.Epoch, v, record, "returned to rotation"); err != nil {
				return err
			}
		case record.Drain && record.Permit < target:
			// Drained: permit the restart once the load balancer stopped
			// sending it requests and the in-flight grace passed since it
			// was first seen to, not since the drain was asked for: the
			// load balancer may apply it late.
			busy[v.seat.Group] = true
			since := record.DrainedAt
			if v.inLB {
				if !v.backend.Drained {
					delete(c.drained, v.seat.Node)
					continue
				}
				first, seen := c.drained[v.seat.Node]
				if !seen {
					c.drained[v.seat.Node] = now
					first = now
				}
				since = first
			}
			if now.Sub(since) < DefaultDrainGrace {
				continue
			}
			record.Permit = target
			if err := c.put(ctx, snapshot.Epoch, v, record, "restart permitted"); err != nil {
				return err
			}
		case record.Drain, v.wanted && !v.done && record.Permit >= target:
			// Restarting under a permit. A seat that never serves holds
			// its group until a newer desired generation (a rollback)
			// supersedes the permit.
			busy[v.seat.Group] = true
		}
	}
	if c.Hold != nil {
		reason, err := c.Hold(ctx)
		if err != nil {
			return err
		}
		if reason != "" {
			slog.DebugContext(ctx, "terrabase seats wait: "+reason, "component", "seatrollout")
			return nil
		}
	}
	var pending []view
	for _, v := range views {
		if v.wanted && !v.done && v.record.Permit < v.desired.Generation && !v.record.Drain && !busy[v.seat.Group] {
			pending = append(pending, v)
		}
	}
	// Seats the load balancer does not serve go first: restarting them
	// costs no capacity.
	slices.SortFunc(pending, func(a, b view) int {
		if a.serving() != b.serving() {
			if a.serving() {
				return 1
			}
			return -1
		}
		return cmp.Compare(a.seat.Node, b.seat.Node)
	})
	for _, v := range pending {
		if busy[v.seat.Group] {
			continue
		}
		busy[v.seat.Group] = true
		record := v.record
		if !v.serving() {
			record.Permit = v.desired.Generation
			if err := c.put(ctx, snapshot.Epoch, v, record, "restart permitted; the seat serves no requests"); err != nil {
				return err
			}
			continue
		}
		if !slices.ContainsFunc(views, func(other view) bool { return other.seat.Node != v.seat.Node && other.serving() }) {
			slog.DebugContext(ctx, "terrabase seat waits: draining it would leave no healthy seat", "component", "seatrollout", "seat", v.seat.Node)
			continue
		}
		record.Drain, record.DrainedAt = true, now
		if err := c.put(ctx, snapshot.Epoch, v, record, "drained for its restart"); err != nil {
			return err
		}
	}
	return nil
}

func (c *Controller) put(ctx context.Context, epoch uint64, v view, record Seat, what string) error {
	record.Node, record.Epoch = v.seat.Node, epoch
	if _, err := c.Store.Put(ctx, record, v.rev); err != nil {
		return fmt.Errorf("seat %s: %w", v.seat.Node, err)
	}
	if c.Wake != nil {
		c.Wake()
	}
	slog.InfoContext(ctx, "terrabase seat "+what, "component", "seatrollout", "seat", v.seat.Node, "generation", v.desired.Generation, "epoch", epoch)
	return nil
}

// observe reads every seat's record, desired, report and backend.
func (c *Controller) observe(ctx context.Context) ([]view, error) {
	seats, err := c.Seats()
	if err != nil {
		return nil, err
	}
	desired, err := c.Hosts.ListDesired(ctx, terrabase.Role)
	if err != nil {
		return nil, err
	}
	statuses, err := c.Hosts.ListHosts(ctx)
	if err != nil {
		return nil, err
	}
	backends := map[string]Backend{}
	if c.Backends != nil {
		if backends, err = c.Backends(ctx); err != nil {
			return nil, err
		}
	}
	now := c.now()
	views := make([]view, 0, len(seats))
	for _, seat := range seats {
		record, rev, err := c.Store.Get(ctx, seat.Node)
		if err != nil {
			return nil, err
		}
		v := view{seat: seat, record: record, rev: rev}
		if index := slices.IndexFunc(desired, func(d host.Desired) bool { return d.Node == seat.Node }); index >= 0 {
			v.desired = desired[index]
			v.wanted = !v.desired.Withdrawn && v.desired.ManagedMember == nil
		}
		for _, status := range statuses {
			for _, report := range status.Reports {
				if report.Node == seat.Node && report.Role == terrabase.Role && report.Generation == v.desired.Generation &&
					report.Digest == v.desired.Digest && report.State == "running" && now.Sub(report.ObservedAt) < host.ReportMaxAge {
					v.done = true
				}
			}
		}
		v.backend, v.inLB = backends[seat.Backend]
		if seat.Backend != "" && !v.inLB {
			return nil, fmt.Errorf("seat %s: expected load balancer backend %s is unobserved", seat.Node, seat.Backend)
		}
		v.inLB = v.inLB && seat.Backend != ""
		views = append(views, v)
	}
	return views, nil
}

func Open(ctx context.Context, js jetstream.JetStream, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || js.Conn() == nil || fencer == nil || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: seat store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 4, MaxValueSize: 4 << 10,
	})
	if err != nil {
		return nil, fmt.Errorf("seat store: %w", err)
	}
	reader, err := openReader(ctx, js, kv)
	if err != nil {
		return nil, err
	}
	return &Store{Reader: reader, fencer: fencer}, nil
}

// Get returns node's record and its revision; a seat without a record is
// neither drained nor permitted (revision zero).
func (s *Reader) Get(ctx context.Context, node string) (Seat, uint64, error) {
	if !nodeRE.MatchString(node) {
		return Seat{}, 0, fmt.Errorf("%w: seat %q", ErrInvalid, node)
	}
	subject := "$KV." + Bucket + "." + node
	// Drain decisions must observe the leader, never a potentially stale replica.
	entry, err := s.leader.GetLastMsg("KV_"+Bucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return Seat{Node: node}, 0, nil
	}
	if err != nil {
		return Seat{}, 0, fmt.Errorf("read seat %s: %w", node, err)
	}
	if entry == nil || entry.Subject != subject || entry.Sequence == 0 || entry.Header.Get("KV-Operation") != "" || entry.Header.Get(jetstream.MarkerReasonHeader) != "" {
		return Seat{}, 0, fmt.Errorf("%w: malformed or deleted seat %s", ErrInvalid, node)
	}
	var seat Seat
	if err := json.Unmarshal(entry.Data, &seat, json.RejectUnknownMembers(true)); err != nil {
		return Seat{}, 0, fmt.Errorf("%w: seat %s: %v", ErrInvalid, node, err)
	}
	if err := seat.validate(); err != nil || seat.Node != node {
		return Seat{}, 0, fmt.Errorf("%w: seat %s holds %q", ErrInvalid, node, seat.Node)
	}
	return seat, entry.Sequence, nil
}

// Put writes seat at revision (zero creates it) after checking its epoch
// still holds authority, and returns the new revision.
func (s *Store) Put(ctx context.Context, seat Seat, revision uint64) (uint64, error) {
	if err := seat.validate(); err != nil {
		return 0, err
	}
	wire, err := json.Marshal(seat)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, seat.Epoch); err != nil {
		return 0, err
	}
	if revision == 0 {
		return s.kv.Create(ctx, seat.Node, wire)
	}
	return s.kv.Update(ctx, seat.Node, wire, revision)
}

// Drained returns the seats held drained.
func (s *Reader) Drained(ctx context.Context) (map[string]bool, error) {
	keys, err := s.kv.ListKeys(ctx)
	if err != nil {
		return nil, fmt.Errorf("list seats: %w", err)
	}
	defer keys.Stop()
	drained := map[string]bool{}
	for node := range keys.Keys() {
		seat, _, err := s.Get(ctx, node)
		if err != nil {
			return nil, err
		}
		if seat.Drain {
			drained[node] = true
		}
	}
	return drained, nil
}

// Granted is the host restart gate: a static TerraBase member restarts only
// into a desired generation its seat permits. Every other role restarts
// freely.
func (s *Store) Granted(ctx context.Context, node string, desired host.Desired) (bool, error) {
	if desired.Role != terrabase.Role {
		return true, nil
	}
	seat, _, err := s.Get(ctx, node)
	if err != nil {
		return false, err
	}
	return desired.Generation <= seat.Permit, nil
}

func OpenKVStore(ctx context.Context, js jetstream.JetStream, replicas int) (*KVStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI resource store requires JetStream and one to five replicas")
	}

	desired, err := openBucket(ctx, js, replicas, desiredBucket, "Desired OCI regional resource specs", 5)
	if err != nil {
		return nil, err
	}
	observed, err := openBucket(ctx, js, replicas, observedBucket, "Last observed OCI regional resource state and drift", 1)
	if err != nil {
		return nil, err
	}
	return &KVStore{desired: desired, observed: observed}, nil
}

func openBucket(ctx context.Context, js jetstream.JetStream, replicas int, bucket, description string, history uint8) (jetstream.KeyValue, error) {
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: bucket, Description: description,
		MaxValueSize: maxRecordBytes, History: history, Storage: jetstream.FileStorage, Replicas: replicas, Compression: true})
	if err == nil {
		return kv, nil
	}
	if !errors.Is(err, jetstream.ErrBucketExists) {
		return nil, fmt.Errorf("create %s bucket: %w", bucket, err)
	}
	kv, err = js.KeyValue(ctx, bucket)
	if err != nil {
		return nil, fmt.Errorf("open %s bucket: %w", bucket, err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("inspect %s bucket: %w", bucket, err)
	}
	config := status.Config()
	if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.MaxValueSize > maxRecordBytes {
		return nil, fmt.Errorf("existing %s bucket has incompatible durability limits", bucket)
	}
	return kv, nil
}

func (s *KVStore) List(ctx context.Context, region, kind string) ([]Desired, error) {
	probe := Key{Region: region, Kind: kind, Name: "x"}
	if err := probe.Validate(); err != nil {
		return nil, err
	}
	lister, err := s.desired.ListKeysFiltered(ctx, region+"."+kind+".*")
	if err != nil {
		if errors.Is(err, jetstream.ErrNoKeysFound) {
			return nil, nil
		}
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	var keys []string
	seen := make(map[string]bool)
	for key := range lister.Keys() {
		if len(keys) >= maxListedKeys {
			_ = lister.Stop()
			return nil, errors.New("OCI desired key list exceeds its safety bound")
		}
		if !seen[key] {
			seen[key] = true
			keys = append(keys, key)
		}
	}
	// The lister closes early without an error when ctx ends mid-listing;
	// a truncated listing must not look complete.
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	slices.Sort(keys)
	records := make([]Desired, 0, len(keys))
	for _, subject := range keys {
		entry, err := s.desired.Get(ctx, subject)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read OCI desired record: %w", err)
		}
		desired, err := decodeDesired(entry.Value(), entry.Revision())
		if err != nil {
			return nil, err
		}
		if desired.Key.subject() != subject {
			return nil, errors.New("OCI desired record key differs from its bucket key")
		}
		records = append(records, desired)
	}
	return records, nil
}

func (s *KVStore) Get(ctx context.Context, key Key) (Desired, error) {
	if err := key.Validate(); err != nil {
		return Desired{}, err
	}
	entry, err := s.desired.Get(ctx, key.subject())
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{}, ErrNotFound
	}
	if err != nil {
		return Desired{}, fmt.Errorf("read OCI desired record: %w", err)
	}
	desired, err := decodeDesired(entry.Value(), entry.Revision())
	if err != nil {
		return Desired{}, err
	}
	if desired.Key != key {
		return Desired{}, errors.New("OCI desired record key differs from its bucket key")
	}
	return desired, nil
}

func (s *KVStore) Put(ctx context.Context, desired Desired) (Desired, error) {
	desired.Operation = nil
	if err := desired.Validate(); err != nil {
		return Desired{}, err
	}
	wire, err := encode(desired)
	if err != nil {
		return Desired{}, err
	}
	current, err := s.Get(ctx, desired.Key)
	switch {
	case errors.Is(err, ErrNotFound):
		revision, err := s.desired.Create(ctx, desired.Key.subject(), wire)
		if errors.Is(err, jetstream.ErrKeyExists) {
			return Desired{}, ErrConflict
		}
		if err != nil {
			return Desired{}, fmt.Errorf("create OCI desired record: %w", err)
		}
		desired.Revision = revision
		return desired, nil
	case err != nil:
		return Desired{}, err
	}
	if desired.Generation <= current.Generation {
		return Desired{}, fmt.Errorf("%w: generation %d does not supersede %d", ErrConflict, desired.Generation, current.Generation)
	}
	if current.Operation != nil && current.Operation.CompletedAt.IsZero() {
		return Desired{}, fmt.Errorf("%w: previous OCI operation awaits observation", ErrConflict)
	}
	desired.Operation = nil
	wire, err = encode(desired)
	if err != nil {
		return Desired{}, err
	}
	revision, err := s.desired.Update(ctx, desired.Key.subject(), wire, current.Revision)
	if err != nil {
		return Desired{}, fmt.Errorf("%w: %w", ErrConflict, err)
	}
	desired.Revision = revision
	return desired, nil
}

func (c *Controller[S, O]) Reconcile(ctx context.Context, epoch uint64) (Result, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()
	c.mu.Lock()
	defer c.mu.Unlock()
	if err := c.validate(); err != nil {
		return Result{}, err
	}
	records, err := c.Store.List(ctx, c.Region, c.Resource.Kind())
	if err != nil {
		return Result{}, err
	}
	var result Result
	var failures []error
	for _, desired := range records {
		status, err := c.reconcileOne(ctx, epoch, desired)
		result.Observed++
		switch {
		case status.Deleted:
			result.Deleted++
		case status.Foreign:
			result.Foreign++
		case status.InSync:
			result.InSync++
		default:
			result.Drifted++
		}
		if status.Applied {
			result.Applied++
		}
		if err != nil {
			result.Failed++
			status.Error = err.Error()
			if errors.Is(err, ErrFenced) || ctx.Err() != nil {
				return result, err
			}
			failures = append(failures, fmt.Errorf("%s: %w", desired.Key, err))
		}
		if !status.Deleted {
			if err := c.Store.PutStatus(ctx, status); err != nil {
				return result, err
			}
		}
	}
	return result, errors.Join(failures...)
}

func (c *Controller[S, O]) guard(ctx context.Context, epoch uint64) error {
	if err := c.Authority.Guard(ctx, epoch); err != nil {
		return fmt.Errorf("%w: %w", ErrFenced, err)
	}
	return nil
}

func (c *Controller[S, O]) reconcileOne(ctx context.Context, epoch uint64, desired Desired) (Status, error) {
	status := Status{Key: desired.Key, Generation: desired.Generation, SpecDigest: desired.SpecDigest, ObservedAt: c.now(),
		Policy: desired.Policy}
	if desired.Operation != nil {
		status.OperationID = desired.Operation.ID
	}
	if desired.Key.Region != c.Region || desired.Key.Kind != c.Resource.Kind() {
		return status, errors.New("OCI desired record is outside this controller's scope")
	}
	var spec S
	if err := json.Unmarshal(desired.Spec, &spec, json.RejectUnknownMembers(true)); err != nil {
		return status, fmt.Errorf("decode OCI desired spec: %w", err)
	}
	target := Target[S]{Key: desired.Key, Generation: desired.Generation, SpecDigest: desired.SpecDigest,
		Ownership: c.Ownership, Spec: spec, Deleting: desired.Tombstone != nil,
		Guard: func(ctx context.Context) error {
			if err := c.guard(ctx, epoch); err != nil {
				return err
			}
			var err error
			desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
			if err != nil {
				return err
			}
			return c.guard(ctx, epoch)
		}}
	bindOperation := func(ctx context.Context) context.Context {
		target.OperationID = desired.Operation.ID
		status.OperationID = target.OperationID
		ctx = ociclient.WithWireAttempt(ctx, func(request *http.Request) (func(*http.Response, error, bool) error, error) {
			return checkpointRequest(request.Context(), request, &desired, c.Store, epoch, c.now)
		})
		return context.WithValue(ociclient.WithAuthority(ctx, target.Fence), operationContextKey{}, operationContext{id: target.OperationID,
			record: func(ctx context.Context, id string) error {
				if id == "" {
					return errors.New("OCI mutation returned no work request")
				}
				if err := c.guard(ctx, epoch); err != nil {
					return err
				}
				if !slices.Contains(desired.Operation.WorkRequests, id) {
					operation := *desired.Operation
					operation.WorkRequests = append(slices.Clone(operation.WorkRequests), id)
					desired.Operation = &operation
				}
				var err error
				desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), false)
				return err
			}})
	}
	if desired.Operation != nil && len(desired.Operation.WorkRequests) != 0 {
		// Reading an original accepted work request needs live authority but
		// must not claim a new mutation before its outcome is known.
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
		recovery, ok := any(c.Resource).(interface {
			RecoverWorkRequests(context.Context, []string) error
		})
		if !ok {
			return status, errors.New("OCI resource cannot recover its pending work requests")
		}
		recoveryErr := recovery.RecoverWorkRequests(bindOperation(ctx), desired.Operation.WorkRequests)
		if recoveryErr != nil && !errors.Is(recoveryErr, ErrWorkRequestFailed) {
			return status, fmt.Errorf("recover OCI work request: %w", recoveryErr)
		}
		operation := *desired.Operation
		operation.WorkRequests = nil
		if recoveryErr != nil {
			operation.Failure = recoveryErr.Error()
		}
		desired.Operation = &operation
		if recoveryErr != nil {
			if err := c.guard(ctx, epoch); err != nil {
				return status, err
			}
			var err error
			desired, err = c.Store.SaveOperation(ctx, desired, epoch, c.now(), true)
			if err != nil {
				return status, err
			}
			return status, fmt.Errorf("previous OCI operation failed: %w", recoveryErr)
		}
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
	}
	observed, found, err := c.Resource.Observe(ctx, target)
	if errors.Is(err, ErrForeign) {
		// Never adopt, mutate, or delete an object this controller cannot prove
		// it owns; surface it for an operator instead.
		status.Found, status.Foreign = true, true
		slog.WarnContext(ctx, "withholding foreign OCI resource", "key", desired.Key.String())
		return status, nil
	}
	if err != nil {
		return status, fmt.Errorf("observe: %w", err)
	}
	status.Found = found

	if desired.Tombstone != nil {
		return c.deleteOne(ctx, epoch, &desired, target, observed, found, status, bindOperation)
	}

	plan := c.Resource.Diff(target, observed, found)
	status.Drift = plan.Changes
	status.InSync = plan.Empty()
	if plan.Empty() && desired.Operation != nil && desired.Operation.CompletedAt.IsZero() {
		if err := c.guard(ctx, epoch); err != nil {
			return status, err
		}
		status.OperationID = desired.Operation.ID
		_, err := c.Store.SaveOperation(ctx, desired, epoch, c.now(), true)
		if err != nil {
			return status, err
		}
	}
	if plan.Empty() {
		return status, nil
	}
	if desired.Operation != nil && !desired.Operation.AppliedAt.IsZero() {
		// The previous full apply finished; fresh observed drift needs new
		// tokens rather than deduplicating against that finished request.
		desired.Operation = nil
	}
	if err := target.Fence(ctx); err != nil {
		return status, err
	}
	ctx = bindOperation(ctx)
	if err := c.Resource.Apply(ctx, target, observed, found, plan); err != nil {
		return status, fmt.Errorf("apply: %w", err)
	}
	if err := c.guard(ctx, epoch); err != nil {
		return status, err
	}
	operation := *desired.Operation
	operation.AppliedAt = c.now()
	desired.Operation = &operation
	if _, err := c.Store.SaveOperation(ctx, desired, epoch, c.now(), false); err != nil {
		return status, err
	}
	status.Applied = true
	slog.InfoContext(ctx, "OCI resource drift corrected", "key", desired.Key.String(), "plan", plan.String())
	recordDecision(ctx, desired, epoch, decisionlog.KindOCIDriftCorrected,
		fmt.Sprintf("Corrected drift on %s (%d changes)", desired.Key, len(plan.Changes)),
		"The observed OCI resource differed from its enforced desired spec.", plan)
	return status, nil
}

func (s Spec) Validate() error {
	if !strings.HasPrefix(s.LoadBalancerID, "ocid1.loadbalancer.") || s.BackendSet == "" || len(s.BackendSet) > 32 {
		return errors.New("load balancer spec requires a load balancer OCID and backend set name")
	}
	if len(s.Backends) > maxBackends {
		return errors.New("load balancer spec exceeds its backend bound")
	}
	seen := map[string]bool{}
	for _, backend := range s.Backends {
		address, err := netip.ParseAddr(backend.IP)
		if err != nil || !address.Is4() || !address.IsPrivate() {
			return fmt.Errorf("load balancer backend %q is not a private IPv4 address", backend.IP)
		}
		if backend.Port < 1 || backend.Port > 65535 {
			return errors.New("load balancer backend port is out of range")
		}
		if seen[backend.key()] {
			return errors.New("load balancer spec repeats a backend")
		}
		seen[backend.key()] = true
	}
	if !s.serves() && !s.AllowEmpty {
		return errors.New("load balancer spec has no serving backend and does not allow it")
	}
	return nil
}

// serves reports whether any backend is left in rotation.
func (s Spec) serves() bool {
	return slices.ContainsFunc(s.Backends, func(b Backend) bool { return !b.Drain })
}

func (r Reconciler) Observe(ctx context.Context, target ociresource.Target[Spec]) (Observed, bool, error) {
	if err := target.Spec.Validate(); err != nil {
		return Observed{}, false, err
	}
	balancer, err := r.API.GetLoadBalancer(ctx, target.Spec.LoadBalancerID)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		return Observed{}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if balancer.ID != target.Spec.LoadBalancerID || !target.Ownership.Owns(target.Key, balancer.Tags) {
		return Observed{}, true, ociresource.ErrForeign
	}
	backends, err := r.API.ListBackends(ctx, target.Spec.LoadBalancerID, target.Spec.BackendSet)
	if target.Deleting && errors.Is(err, ociresource.ErrGone) {
		return Observed{LoadBalancer: balancer}, false, nil
	}
	if err != nil {
		return Observed{}, false, err
	}
	if target.Deleting && len(backends) == 0 {
		return Observed{LoadBalancer: balancer}, false, nil
	}
	return Observed{LoadBalancer: balancer, Backends: backends}, true, nil
}

func changes(spec Spec, observed []Backend) delta {
	have := map[string]Backend{}
	for _, backend := range observed {
		have[backend.key()] = backend
	}
	want := map[string]bool{}
	var d delta
	for _, backend := range spec.Backends {
		backend.weight, backend.backup, backend.offline, backend.name = defaultWeight, false, false, ""
		want[backend.key()] = true
		current, ok := have[backend.key()]
		switch {
		case !ok:
			d.create = append(d.create, backend)
		case current.Drain == backend.Drain && current.weight == defaultWeight && !current.backup && !current.offline:
		case backend.Drain:
			backend.name = current.name
			d.drain = append(d.drain, backend)
		default:
			backend.name = current.name
			d.undrain = append(d.undrain, backend)
		}
	}
	for _, backend := range observed {
		if !want[backend.key()] {
			d.remove = append(d.remove, backend)
		}
	}
	for _, list := range [][]Backend{d.create, d.undrain, d.drain, d.remove} {
		slices.SortFunc(list, func(a, b Backend) int { return strings.Compare(a.key(), b.key()) })
	}
	return d

func (Reconciler) Diff(target ociresource.Target[Spec], observed Observed, found bool) ociresource.Plan {
	var plan ociresource.Plan
	if !found {
		plan.Add("blocked", "load balancer %s is not visible", target.Spec.LoadBalancerID)
		return plan
	}
	d := changes(target.Spec, observed.Backends)
	for _, backend := range d.create {
		plan.Add("add-backend", "%s %s", backend.Name(), state(backend))
	}
	for _, backend := range d.undrain {
		plan.Add("serve-backend", "%s", backend.Name())
	}
	for _, backend := range d.drain {
		plan.Add("drain-backend", "%s", backend.Name())
	}
	for _, backend := range d.remove {
		plan.Add("remove-backend", "%s", backend.Name())
	}
	if d.restamp(target, observed.LoadBalancer.Tags) {
		plan.Add("tag", "restamp ownership generation %d", target.Generation)
	}
	return plan
}

// checkHealthy runs after the plan's creates and undrains. It holds the
// rest of the plan unless a backend the spec keeps serving reports health
// OK. A backend this plan created has never been checked, so it does not
// count.
func (r Reconciler) checkHealthy(ctx context.Context, spec Spec, observed []Backend) error {
	unhealthy, err := r.API.UnhealthyBackends(ctx, spec.LoadBalancerID, spec.BackendSet)
	if err != nil {
		return fmt.Errorf("read load balancer backend health: %w", err)
	}
	existing := map[string]Backend{}
	for _, backend := range observed {
		existing[backend.key()] = backend
	}
	for _, backend := range spec.Backends {
		current, ok := existing[backend.key()]
		if ok && !backend.Drain && !unhealthy[current.Name()] {
			return nil
		}
	}
	return fmt.Errorf("%w: hold draining or removing a serving backend", ErrNoHealthyBackend)
}

// mutate fences, runs one load balancer mutation and waits for its work
// request.
func (r Reconciler) mutate(ctx context.Context, target ociresource.Target[Spec], call func() (string, error)) error {
	if err := target.Fence(ctx); err != nil {
		return err
	}
	id, err := call()
	if err != nil {
		return err
	}
	if id == "" {
		return errors.New("load balancer mutation returned no work request")
	}
	return r.API.WaitWorkRequest(ctx, id)

func (r Reconciler) Apply(ctx context.Context, target ociresource.Target[Spec], observed Observed, found bool, _ ociresource.Plan) error {
	if !found {
		return fmt.Errorf("load balancer %s is not visible; the reconciler never creates load balancers", target.Spec.LoadBalancerID)
	}
	if err := target.Spec.Validate(); err != nil {
		return err
	}
	id, set := target.Spec.LoadBalancerID, target.Spec.BackendSet
	d := changes(target.Spec, observed.Backends)
	update := func(b Backend) (string, error) { return r.API.UpdateBackend(ctx, id, set, b) }
	run := func(verb string, backends []Backend, call func(Backend) (string, error)) error {
		for _, backend := range backends {
			if err := r.mutate(ctx, target, func() (string, error) { return call(backend) }); err != nil {
				return fmt.Errorf("%s load balancer backend %s: %w", verb, backend.Name(), err)
			}
		}
		return nil
	}
	if err := run("add", d.create, func(b Backend) (string, error) { return r.API.CreateBackend(ctx, id, set, b) }); err != nil {
		return err
	}
	if err := run("serve", d.undrain, update); err != nil {
		return err
	}
	// Only a spec that serves nothing (allowed by AllowEmpty) skips the
	// guard: no backend could ever satisfy it.
	if len(d.outOfRotation(observed.Backends)) > 0 && target.Spec.serves() {
		if err := r.checkHealthy(ctx, target.Spec, observed.Backends); err != nil {
			return err
		}
	}
	if err := run("drain", d.drain, update); err != nil {
		return err
	}
	if err := run("remove", d.remove, func(b Backend) (string, error) { return r.API.DeleteBackend(ctx, id, set, b.Name()) }); err != nil {
		return err
	}
	if d.restamp(target, observed.LoadBalancer.Tags) {
		balancer := observed.LoadBalancer
		if !d.empty() {
			// The backend work requests advanced the load balancer's ETag;
			// restamp against a fresh read, and only while it is still owned.
			fresh, err := r.API.GetLoadBalancer(ctx, id)
			if err != nil {
				return fmt.Errorf("re-read load balancer before restamp: %w", err)
			}
			if fresh.ID != id || !target.Ownership.Owns(target.Key, fresh.Tags) {
				return ociresource.ErrForeign
			}
			balancer = fresh
		}
		tags := balancer.Tags.Merge(target.Ownership.Stamp(target.Key, target.Generation, target.SpecDigest))
		if err := r.mutate(ctx, target, func() (string, error) { return r.API.UpdateTags(ctx, id, balancer.ETag, tags) }); err != nil {
			return fmt.Errorf("restamp load balancer ownership: %w", err)
		}
	}
	return nil
}

func Publish(ctx context.Context, store ociresource.Store, key ociresource.Key, policy ociresource.DriftPolicy, spec Spec) (bool, error) {
	if key.Kind != Kind {
		return false, errors.New("load balancer backends must be published under the lb-backends kind")
	}
	return ociresource.Publish(ctx, store, key, policy, spec)
}

